import React, { useState, useEffect } from 'react';

const Autocomplete = () => {
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [selected, setSelected] = useState(null);

  const items = [
    { id: 1, name: 'Apple' },
    { id: 2, name: 'Banana' },
    { id: 3, name: 'Cherry' },
    { id: 4, name: 'Date' },
    // ... your list of items
  ];

  useEffect(() => {
    const queryLength = query.length;
    const filteredItems = items.filter((item) => {
      const text = item.name.toLowerCase();
      const queryText = query.toLowerCase();
      return text.includes(queryText) && text.indexOf(queryText) === 0;
    });

    setSuggestions(filteredItems.slice(0, 10));
  }, [query]);

  const handleChange = (event) => {
    setQuery(event.target.value);
  };

  const handleSelect = (event) => {
    const selectedId = event.target.dataset.id;
    const selectedItem = items.find((item) => item.id === parseInt(selectedId));

    setSelected(selectedItem);
  };

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={handleChange}
        placeholder="Type to search..."
      />
      <ul>
        {suggestions.map((suggestion) => (
          <li key={suggestion.id}>
            <a href="#" data-id={suggestion.id} onClick={handleSelect}>
              {suggestion.name}
            </a>
          </li>
        ))}
      </ul>
      {selected && (
        <p>
          You selected: <strong>{selected.name}</strong>
        </p>
      )}
    </div>
  );
};

export default Autocomplete;
